/* Compute-only TU. saturn_vme.h is generated by the existing RTL-derived
 * kernel preparation API; no opcode or register grouping is invented here.
 */
#ifdef _OPENMP
#error "controller-dispatched VME compute must be compiled without OpenMP"
#endif
#include "vme_split.h"
#include "vme_gemm_2x2_bias.c"

int iris_vme_split_compute(const iris_vme_split_work *w,
                           size_t *completed_blocks) {
  unsigned hart = iris_vme_split_hart();
  if (hart > 1) return IRIS_VME_SPLIT_ROLE;
  if (!completed_blocks) return IRIS_VME_SPLIT_SHAPE;
  int status = iris_vme_split_validate_work(w);
  if (status) return status;
  if (!(w->worker_mask & (1U << hart))) return IRIS_VME_SPLIT_ROLE;
  if (w->tile_edge != VME_TILE_EDGE || w->alignment_bytes != VME_ALIGN_BYTES)
    return IRIS_VME_SPLIT_CONFIG;
  uintptr_t result = (uintptr_t)completed_blocks;
  if (result % _Alignof(size_t) || sizeof(*completed_blocks) > UINTPTR_MAX - result)
    return IRIS_VME_SPLIT_ALIGNMENT;
  const void *bases[] = {w->at, w->bp, w->cp, w};
  size_t bytes[] = {w->m * w->k, w->k * w->n,
                    w->m * w->n * sizeof(int32_t), sizeof(*w)};
  for (unsigned i = 0; i < 4; ++i)
    if (result < (uintptr_t)bases[i] + bytes[i] &&
        (uintptr_t)bases[i] < result + sizeof(*completed_blocks))
      return IRIS_VME_SPLIT_ALIAS;
  vme_enable();
  size_t te = vme_vsettnt_e8w4_alt((size_t)-1);
  if (te != w->tile_edge) return IRIS_VME_SPLIT_CONFIG;
  unsigned workers = (w->worker_mask & 1U) + ((w->worker_mask >> 1) & 1U);
  unsigned rank = hart == 0 ? 0 : (w->worker_mask & 1U);
  *completed_blocks = 0;
  for (size_t block = rank; block < w->block_count; block += workers) {
    size_t m0 = (block / w->block_columns) * (2 * te);
    size_t n0 = (block % w->block_columns) * (2 * te);
    if (w->m - m0 >= 2 * te && w->n - n0 >= 2 * te) {
      gemm_2x2_bias_block(w->cp, w->at, w->bp, (const int32_t *)0,
                          w->m, w->n, w->k, te, m0, n0);
    } else {
      for (size_t i = m0; i < w->m && i - m0 < 2 * te; i += te)
        for (size_t j = n0; j < w->n && j - n0 < 2 * te; j += te)
          gemm_tile_bias(w->cp, w->at, w->bp, (const int32_t *)0,
                         w->m, w->n, w->k, i, j,
                         w->m - i < te ? w->m - i : te,
                         w->n - j < te ? w->n - j : te);
    }
    ++*completed_blocks;
  }
#if defined(__riscv)
  /* Order all vector output writes before the caller publishes completion.
   * This is an architectural fence, not an assertion about DRAM D-channel
   * acknowledgements or a measurement of physical store-buffer occupancy. */
  __asm__ volatile("fence rw,rw" ::: "memory");
#endif
  return IRIS_VME_SPLIT_OK;
}
